replacement:
// A second visual-only owner of an already submitted block needs no new
// geometry. Rescheduling here would advance the desired revision and discard
// a concurrent accepted edit replacement. Preserve its old visible resource
// until that current revision submits, including confirmed-empty blocks.
const bool visual_handover = mesh_flag && !collision_flag && block->is_loaded && block->mesh_viewers.get() > 1;
if (!visual_handover) try_schedule_mesh_update(*block);

// Other viewer/flag combinations keep upstream scheduling: mixing viewers
// with collisions and viewers without still needs individual collider handling.
